class Solution { fun colorTheGrid(m:Int,n:Int):Int{val mod=1_000_000_007L;var limit=1;repeat(m){limit*=3};val states=(0 until limit).filter{stateValue->var value=stateValue;var previous=-1;var valid=true;repeat(m){val color=value%3;value/=3;if(color==previous)valid=false;previous=color};valid};val compatible=Array(states.size){BooleanArray(states.size)};for(i in states.indices)for(j in states.indices){var a=states[i];var b=states[j];compatible[i][j]=true;repeat(m){if(a%3==b%3)compatible[i][j]=false;a/=3;b/=3}};var dp=LongArray(states.size){1};repeat(n-1){val next=LongArray(states.size);for(current in states.indices)for(previous in states.indices)if(compatible[previous][current])next[current]=(next[current]+dp[previous])%mod;dp=next};return (dp.sum()%mod).toInt()} }
